409:   // Renderiza el PDF del PAA desde el backend y lo sube a Nuxeo.
410:   // Es invocado automáticamente por guardarPaa() tras persistir el orden.
411:   private guardarPdfPaa(): void {
412:     this.PlanAnualAuditoriaMid.get(`plantilla/${this.id}?auditoria-padre=true`)
413:       .subscribe({
414:         next: (res) => {
415:           if (res?.Data) {
416:             const base64 = res.Data;
417: 
418:             const payload = {
419:               IdTipoDocumento: environment.TIPO_DOCUMENTO.PLANES_AUDITORIA,
420:               nombre: this.id,
421:               descripcion: "Documento pdf, auditorias de plan de auditoria",
422:               metadatos: {},
423:               file: base64,
424:             };
425: 
426:             // Subir el PDF renderizado a Nuxeo
427:             this.nuxeoService.guardarArchivos([payload]).subscribe({
428:               next: (response: any) => {
429:                 const documento = response[0];
430:                 // Determinar el tipo de documento según el modo de edición:
431:                 // - Edición extraordinaria → PLAN_ANUAL_AUDITORIA_ACTUALIZADO
432:                 // - Flujo normal           → PLAN_ANUAL_AUDITORIA_ORIGINAL
433:                 this.guardarReferenciaPdf(
434:                   documento,
435:                   "Plan Auditoria",
436:                   this.id,
437:                   this.modoEditarExtraordinario
438:                     ? environment.TIPO_DOCUMENTO_PARAMETROS.PLAN_ANUAL_AUDITORIA_ACTUALIZADO
439:                     : environment.TIPO_DOCUMENTO_PARAMETROS.PLAN_ANUAL_AUDITORIA_ORIGINAL
440:                 );
441:               },
442:               error: (error) => {
443:                 console.error("Error al subir el PDF a Nuxeo:", error);
444:                 this.alertaService.showErrorAlert(
445:                   "El orden fue guardado, pero ocurrió un error al generar el documento PDF."
446:                 );
447:               },
448:             });
449:           } else {
450:             this.alertaService.showErrorAlert(
451:               "El orden fue guardado, pero no se pudo renderizar el documento PDF."
452:             );
453:           }
454:         },
455:         error: (error) => {
456:           console.error("Error al renderizar el PDF:", error);
457:           this.alertaService.showErrorAlert(
458:             "El orden fue guardado, pero ocurrió un error al renderizar el documento PDF."
459:           );
460:         },
461:       });
462:   }
