464:   // Registra en el sistema la referencia del documento subido a Nuxeo.
465:   // Es invocado por guardarPdfPaa() tras una subida exitosa a Nuxeo.
466:   private guardarReferenciaPdf(
467:     nuxeoResponse: any,
468:     referenciaTipo: string,
469:     referenciaId: string,
470:     tipoId: number
471:   ): void {
472:     if (nuxeoResponse?.res?.Enlace) {
473:       this.referenciaPdfService
474:         .guardarReferencia(
475:           nuxeoResponse.res,
476:           referenciaTipo,
477:           referenciaId,
478:           tipoId
479:         )
480:         .subscribe({
481:           next: () => {
482:             this.alertaService.showSuccessAlert(
483:               "El Plan Anual de Auditoría fue guardado exitosamente."
484:             );
485:           },
486:           error: (error) => {
487:             console.error("Error al guardar la referencia del PDF:", error);
488:             this.alertaService.showErrorAlert(
489:               "El orden fue guardado, pero ocurrió un error al registrar el documento PDF."
490:             );
491:           },
492:         });
493:     } else {
494:       // Si Nuxeo no devuelve enlace se notifica el éxito del guardado principal
495:       // y se advierte en consola para trazabilidad
496:       console.warn("Nuxeo no devolvió un enlace para el documento.");
497:       this.alertaService.showSuccessAlert(
498:         "El Plan Anual de Auditoría fue guardado exitosamente."
499:       );
500:     }
501:   }
