12: export function idAcademico(valor: any): number {
13:   return Number(valor?.Id ?? valor ?? 0);
14: }
15: 
16: export function nivelPrograma(programa: any): any {
17:   let nivel = programa.NivelFormacionId;
18:   const visitados = new Set<number>();
19:   while (nivel?.NivelFormacionPadreId && !visitados.has(idAcademico(nivel))) {
20:     visitados.add(idAcademico(nivel));
21:     nivel = nivel.NivelFormacionPadreId;
22:   }
23:   return nivel;
24: }
25: 
26: export function esAdministradorProgramas(roles: unknown): boolean {
27:   const globales = ['ADMIN_SGA', 'VICERRECTOR', 'ASESOR_VICE', 'ADMISIONES_REG'];
28:   return Array.isArray(roles) && roles.some(rol =>
29:     globales.includes(String(rol).split('/').pop()!.trim().toUpperCase()));
30: }
