32: @Injectable({ providedIn: 'root' })
33: export class FiltrosProgramaService {
34:   constructor(
35:     private proyectos: ProyectoAcademicoService,
36:     private oikos: OikosService,
37:     private auth: ImplicitAutenticationService,
38:     private usuarios: UserService,
39:     private admisiones: SgaAdmisionesMid,
40:   ) {}
41: 
42:   async cargar(): Promise<{ programas: any[]; facultades: OpcionPrograma[] }> {
43:     const roles = await this.auth.getRole();
44:     const respuesta = await firstValueFrom(this.proyectos.get('proyecto_academico_institucion?query=Activo:true&limit=0'));
45:     let programas = this.lista(respuesta).filter(p => idAcademico(p) > 0 && idAcademico(p.FacultadId) > 0);
46:     if (!esAdministradorProgramas(roles)) {
47:       const tercero = await this.usuarios.getPersonaId();
48:       if (!tercero) {
49:         programas = [];
50:       } else {
51:         const vinculaciones = await firstValueFrom(this.admisiones.get<RespFormat<DependenciasVinculacionTercero>>(
52:           'admision/dependencia_vinculacion_tercero/' + tercero));
53:         const dependencias = new Set((vinculaciones?.Data?.DependenciaId || []).map(Number));
54:         programas = programas.filter(p => dependencias.has(idAcademico(p.DependenciaId)));
55:       }
56:     }
57:     const ids = [...new Set(programas.map(p => idAcademico(p.FacultadId)))];
58:     const facultades = await Promise.all(ids.map(async Id => {
59:       const respuesta: any = await firstValueFrom(this.oikos.get('dependencia/' + Id));
60:       return { Id, Nombre: (respuesta?.Data || respuesta).Nombre };
61:     }));
62:     return {
63:       programas: programas.sort((a, b) => a.Nombre.localeCompare(b.Nombre)),
64:       facultades: facultades.sort((a, b) => a.Nombre.localeCompare(b.Nombre)),
65:     };
66:   }
67: 
68:   private lista(respuesta: any): any[] {
69:     return Array.isArray(respuesta) ? respuesta : Array.isArray(respuesta?.Data) ? respuesta.Data : [];
70:   }
71: }

